
.terminal {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  border: 1px solid var(--c-ink);
  background: var(--c-panel);
  font-family: var(--font-console);
  font-size: 12.5px;
  line-height: 1.4;
  color: var(--c-ink);
}

.resources {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  border-bottom: 1px solid var(--c-ink);
}

.resource {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 8px;
  min-width: 0;
  border-right: 1px solid var(--c-steel);
}

.resource:last-child {
  border-right: none;
}

.resource-label {
  font-size: 11px;
  color: var(--c-slate);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.resource-value {
  font-size: 15px;
  font-weight: bold;
  color: var(--c-signal);
}

.facilities {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.facility {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 9px;
  min-width: 0;
  border-bottom: 1px solid var(--c-steel);
  border-right: 1px solid var(--c-steel);
}

.facility:nth-child(2n) {
  border-right: none;
}

.facility-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.facility-state {
  flex: none;
  font-size: 11.5px;
  padding: 1px 6px;
  border: 1px solid currentColor;
}

.is-active {
  color: var(--c-signal);
}

.is-recovered {
  color: var(--c-ink);
}

.is-idle {
  color: var(--c-slate);
}

.is-lost {
  color: var(--c-warn);
}

.recover {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: 1px solid var(--c-signal);
  background: transparent;
  color: var(--c-signal);
  font-family: inherit;
  font-size: 11.5px;
  cursor: pointer;
}

.recover:active:not(:disabled) {
  background: var(--c-signal);
  color: var(--c-panel);
}

.recover:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.recover:focus-visible {
  outline: 2px solid var(--c-signal);
  outline-offset: 2px;
}

.recover-icon {
  width: 11px;
  height: 11px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: square;
}

@media (max-width: 560px) {
  .resources {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .resource {
    border-bottom: 1px solid var(--c-steel);
  }

  .facilities {
    grid-template-columns: minmax(0, 1fr);
  }

  .facility {
    border-right: none;
  }
}
